import itertools
import json

def solve():
    houses = [1, 2, 3, 4]

    names = ['Eric', 'Alice', 'Peter', 'Arnold']
    hair_colors = ['blonde', 'black', 'red', 'brown']
    sports = ['swimming', 'soccer', 'basketball', 'tennis']

    solutions = []

    for hair in itertools.permutations(hair_colors):
        # 7. Red hair is directly left of black hair
        if hair.index('red') + 1 != hair.index('black'):
            continue

        idx_red = hair.index('red')
        idx_black = hair.index('black')
        idx_blonde = hair.index('blonde')

        for sport in itertools.permutations(sports):
            # 1. Soccer is not in the second house
            if sport[1] == 'soccer':
                continue

            # 4. Black hair -> Tennis
            if sport[idx_black] != 'tennis':
                continue

            # 3. Blonde is somewhere to the right of Basketball
            if not (idx_blonde > sport.index('basketball')):
                continue

            for name in itertools.permutations(names):
                # 2. Eric has blonde hair
                if name[idx_blonde] != 'Eric':
                    continue

                # 5. Arnold is somewhere to the left of the person with red hair
                if not (name.index('Arnold') < idx_red):
                    continue

                # 6. Alice loves swimming
                if name[sport.index('swimming')] != 'Alice':
                    continue

                solutions.append((name, hair, sport))

    # Choose the first solution (the puzzle should yield a unique solution)
    name_sol, hair_sol, sport_sol = solutions[0]

    rows = []
    for i, h in enumerate(houses):
        rows.append([str(h), name_sol[i], hair_sol[i], sport_sol[i]])

    output = {
        "solution": {
            "header": ["House", "Name", "HairColor", "FavoriteSport"],
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve()
